  T+=intents.length;
  const byRef={};
  for(const e of ev){ (byRef[e.intentRef]=byRef[e.intentRef]||[]).push(e); }
  byItem[it.id]={n:intents.length,evCount:ev.length,intents,byRef,status:it.status};
}
